        return fontNameSize + "<CLR " + directionColor + ">" + directionStr  + "</CLR>" + "\n" +
                              "<CLR " + distanceColor + ">" + prefixPostfix[0] + distanceStr + prefixPostfix[1] + "</CLR></FNT>";
    }
