}

//Straight lines
if (isStraightLine){
    if (!IsEmpty(directionStr) && !IsEmpty(distanceStr)){ //If Direction and Distance are both NOT Empty
        return fontNameSize + "<CLR " + directionColor + ">" + directionStr  + "</CLR>" + "\n" +
